local function _khtkuqxfg(s)local len=#s local bits=len*8 s=s..char(128)while #s%64~=56 do s=s..char(0)end local hi=floor(bits/4294967296)local lo=bits%4294967296 s=s..char(rs(hi,24)%256,rs(hi,16)%256,rs(hi,8)%256,hi%256,rs(lo,24)%256,rs(lo,16)%256,rs(lo,8)%256,lo%256)local h={1779033703,3144134277,1013904242,2773480762,1359893119,2600822924,528734635,1541459225}for off=1,#s,64 do local w={}for j=0,15 do local p=off+j*4 w[j+1]=((byte(s,p)*256+byte(s,p+1))*256+byte(s,p+2))*256+byte(s,p+3)end for j=17,64 do local x=w[j-15]local y=w[j-2]local a=bx(rr(x,7),rr(x,18),rs(x,3))local b=bx(rr(y,17),rr(y,19),rs(y,10))w[j]=(w[j-16]+a+w[j-7]+b)%4294967296 end local a,b,c,d,e,f,g,z=h[1],h[2],h[3],h[4],h[5],h[6],h[7],h[8]for j=1,64 do local s1=bx(rr(e,6),rr(e,11),rr(e,25))local ch=bx(band(e,f),band(bnot(e),g))local t1=(z+s1+ch+_dhzukk[j]+w[j])%4294967296 local s0=bx(rr(a,2),rr(a,13),rr(a,22))local maj=bx(band(a,b),band(a,c),band(b,c))local t2=(s0+maj)%4294967296 z,g,f,e,d,c,b,a=g,f,e,(d+t1)%4294967296,c,b,a,(t1+t2)%4294967296 end h={(h[1]+a)%4294967296,(h[2]+b)%4294967296,(h[3]+c)%4294967296,(h[4]+d)%4294967296,(h[5]+e)%4294967296,(h[6]+f)%4294967296,(h[7]+g)%4294967296,(h[8]+z)%4294967296}end local out={}for j=1,8 do local x=h[j]out[j]=char(rs(x,24)%256,rs(x,16)%256,rs(x,8)%256,x%256)end return concat(out)end
